grid=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
cells={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==8}
# exact cover tiles: one square and 4 L's
from collections import Counter
squares=[{(r+i,c+j) for i in range(2) for j in range(2)} for r in range(3) for c in range(6) if all((r+i,c+j) in cells for i in range(2) for j in range(2))]
Ls=[]
for r in range(3):
 for c in range(6):
  box={(r+i,c+j) for i in range(2) for j in range(2)}
  if box<=cells:
   for missing in box:
    Ls.append((box-{missing},missing))
def solve(rem, tiles):
 if not rem:
  yield tiles; return
 p=min(rem)
 for tile in Ls:
  sh,missing=tile
  if sh<=rem and p in sh:
   yield from solve(rem-sh,tiles+[('L',sh,missing)])
for sq in squares:
 print('sq',sorted(sq))
 sols=list(solve(cells-sq,[('S',sq,None)]))
 print('solutions',len(sols))
 for sol in sols[:3]: print([(t[0], sorted(t[1]),t[2]) for t in sol])

